<?php if(!defined('SW_APP')){http_response_code(404);exit;}
$filter=$_GET['status']??'todos';if(!is_string($filter)||!in_array($filter,['todos','activo','borrador','finalizado'],true))$filter='todos';$rows=raffle_list();$counts=['todos'=>count($rows),'activo'=>0,'borrador'=>0,'finalizado'=>0];foreach($rows as $r)$counts[$r['status']]++;
$filtered=array_filter($rows,fn($r)=>$filter==='todos'||$r['status']===$filter);?>
<div class="page-heading"><p class="eyebrow">GESTIÓN DE SORTEOS</p><div class="raffle-heading-row"><h1>Sorteos</h1><button class="btn primary" type="button" data-open="raffle-dialog">＋ Crear sorteo</button></div><p>Administra los premios, boletos y estados de tus sorteos.</p></div>
<section class="panel raffle-list-panel"><div class="section-heading"><h2>Listado de sorteos</h2><p>Selecciona un estado o busca un sorteo.</p></div><div class="raffle-list-controls"><div class="tabs" role="group" aria-label="Filtrar sorteos"><?php foreach(['todos'=>'Todos','activo'=>'Activos','borrador'=>'Borradores','finalizado'=>'Finalizados'] as $s=>$label): ?><a class="<?=$filter===$s?'active':''?>" href="<?=h(url('sorteos',['status'=>$s]))?>"><?=h($label)?> <span><?=$counts[$s]?></span></a><?php endforeach; ?></div><input type="search" class="search raffle-search" placeholder="Buscar sorteo..." aria-label="Buscar sorteo" data-search="raffle-table"></div><?php if(!$filtered):empty_state('No hay sorteos','Crea un nuevo sorteo o selecciona otro filtro.');else: ?><div class="table-wrap"><table id="raffle-table"><thead><tr><th>Sorteo</th><th>Tipo</th><th>Boletos</th><th>Valor</th><th>Estado</th><th>Acciones</th></tr></thead><tbody><?php foreach($filtered as $r):$id=$r['id'];?><tr><td><div class="item"><?php photo($id,$r['first_photo']);?><div><strong><?=h($r['title'])?></strong><small>#<?=h(substr($id,0,8))?> · <?=h(substr($r['created_at'],0,10))?></small></div></div></td><td><?=h(ucfirst($r['type']))?><small class="muted"><?=h(ucfirst($r['participation_mode']))?></small></td><td><strong><?=number_format((int)$r['registered'])?></strong> <?=$r['close_mode']==='capacidad'?' / '.number_format((int)$r['participation_limit']):($r['participation_mode']==='compartido'?' participaciones':' / '.number_format((int)$r['ticket_count']))?><progress max="<?=$r['close_mode']==='capacidad'?(int)$r['participation_limit']:(int)$r['ticket_count']?>" value="<?=$r['close_mode']==='capacidad'?(int)$r['paid']:(int)$r['distinct_numbers']?>"></progress><small class="muted"><?=h(draw_close_label($r))?></small></td><td><?=money($r['ticket_price_cents'])?></td><td><?=chip($r['status'])?></td><td><div class="actions"><button type="button" class="btn small secondary" data-view-raffle="<?=h(json_encode($r,JSON_INVALID_UTF8_SUBSTITUTE))?>">Ver</button><a class="btn small secondary" href="<?=h(url('participantes',['id'=>$id]))?>">Participantes</a><?php if((int)$r['has_evidence']):?><a class="btn small secondary" href="index.php?view=evidence&amp;id=<?=h($id)?>">Evidencia</a><?php endif;?><?php if($r['status']==='borrador'&&(int)$r['registered']===0&&!(int)$r['has_evidence']):?><button class="btn small secondary" type="button" data-edit-raffle="<?=h(json_encode($r,JSON_INVALID_UTF8_SUBSTITUTE))?>">Editar</button><?php elseif($r['status']!=='finalizado'):?><button class="btn small secondary" type="button" disabled title="Las condiciones de un sorteo publicado no se pueden modificar.">Editar</button><?php endif;form_action('duplicate_raffle',$id,'Duplicar','secondary',null,'¿Crear un nuevo borrador con las condiciones y fotografías de este sorteo? No se copiarán boletos, participantes ni resultados.');if($r['status']==='borrador'):form_action('activate',$id,'Activar','positive',null,'¿Activar el sorteo y generar el compromiso criptográfico irreversible? Sus condiciones se bloquearán cuando se registren boletos o evidencia.');form_action('delete_raffle',$id,'Eliminar','danger',null,'¿Eliminar este borrador?');elseif($r['status']==='activo'):form_action('finish',$id,'Finalizar','secondary',null,'¿Cerrar las inscripciones del sorteo?');elseif($r['status']==='finalizado'):if(!(int)$r['has_evidence']&&!(int)$r['draw_version']):form_action('reactivate',$id,'Reactivar','positive',null,'¿Reabrir el sorteo? Se conservarán sus boletos, participantes y pagos. Volverá a aparecer en los sorteos activos.');else:?><button class="btn small secondary" type="button" disabled title="No se puede reactivar: existe evidencia registrada.">Reactivar</button><?php endif;endif;?></div></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?></section>
